<script>
import Hls from 'hls.js';import {tick,onDestroy} from 'svelte';
let lists=$state([]),active=$state(''),page=$state('playlists'),query=$state(''),group=$state('Tutti'),favorites=$state([]),name=$state(''),url=$state(''),epgUrl=$state(''),message=$state(''),busy=$state(false),selected=$state(null),video=$state(),hls,programs=$state([]),clock=$state(Date.now());
try{let s=JSON.parse(localStorage.getItem('onda')||'{}');lists=s.lists||[];favorites=s.favorites||[];active=s.lists?.[0]?.id||'';}catch{}
const timer=setInterval(()=>clock=Date.now(),30000);onDestroy(()=>{clearInterval(timer);stop();});
let playlist=$derived(lists.find(p=>p.id===active)),channels=$derived(playlist?.channels||[]),groups=$derived(['Tutti','Preferiti',...new Set(channels.map(c=>c.group))]),filtered=$derived(channels.filter(c=>(group==='Tutti'||group==='Preferiti'&&favorites.includes(c.url)||c.group===group)&&c.name.toLowerCase().includes(query.toLowerCase())));
function save(){try{localStorage.setItem('onda',JSON.stringify({lists,favorites}));}catch{message='Spazio locale esaurito: impossibile salvare le modifiche.';}}
function safe(s,base){try{let u=new URL(s,base);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function parse(text,base){if(!text.trimStart().startsWith('#EXTM3U'))throw Error('Il file non è una playlist M3U valida.');let out=[],meta={},epg='';for(let line of text.split(/\r?\n/)){line=line.trim();if(line.startsWith('#EXTM3U'))epg=safe(line.match(/(?:x-tvg-url|url-tvg)="([^"]+)"/i)?.[1]||'',base);else if(line.startsWith('#EXTINF:')){let attrs={};for(let m of line.matchAll(/([\w-]+)="([^"]*)"/g))attrs[m[1]]=m[2];meta={name:line.slice(line.indexOf(',')+1)||'Canale',group:attrs['group-title']||'Altri',tvg:attrs['tvg-id']||'',logo:safe(attrs['tvg-logo'],base)};}else if(line&&!line.startsWith('#')){let u=safe(line,base);if(u)out.push({...meta,name:meta.name||'Canale',group:meta.group||'Altri',url:u});meta={};}}if(!out.length)throw Error('Nessun canale HTTP/HTTPS trovato.');return {channels:out,epg};}
async function fetchText(u){if(!safe(u))throw Error('Inserisci un URL HTTP o HTTPS valido.');let r=await fetch(u,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('La sorgente ha risposto con errore '+r.status);return r.text();}
async function add(file){busy=true;message='';try{let text=file?await file.text():await fetchText(url);let parsed=parse(text,file?undefined:url);let p={id:crypto.randomUUID(),name:name.trim()||file?.name||'La mia playlist',source:file?'':url,...parsed,epg:epgUrl||parsed.epg,updated:Date.now()};lists=[...lists,p];active=p.id;save();name='';url='';epgUrl='';page='channels';loadEpg();}catch(e){message=e.message+' Se la sorgente è remota, verifica che consenta CORS.';}finally{busy=false;}}
async function refresh(p){busy=true;try{let parsed=parse(await fetchText(p.source),p.source);lists=lists.map(x=>x.id===p.id?{...x,...parsed,epg:x.epg||parsed.epg,updated:Date.now()}:x);save();message='Playlist aggiornata.';}catch(e){message='Aggiornamento fallito: '+e.message;}finally{busy=false;}}
function remove(id){lists=lists.filter(p=>p.id!==id);if(active===id)active=lists[0]?.id||'';save();}
function favorite(c){favorites=favorites.includes(c.url)?favorites.filter(u=>u!==c.url):[...favorites,c.url];save();}
function date(s){let m=s?.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?\s*([+-]\d{4})?/);return m?Date.parse(m[1]+'-'+m[2]+'-'+m[3]+'T'+m[4]+':'+m[5]+':'+(m[6]||'00')+(m[7]?m[7].slice(0,3)+':'+m[7].slice(3):'Z')):NaN;}
async function loadEpg(file){programs=[];if(!file&&!playlist?.epg)return;try{let doc=new DOMParser().parseFromString(file?await file.text():await fetchText(playlist.epg),'text/xml');if(doc.querySelector('parsererror'))throw Error('XML non valido');programs=[...doc.querySelectorAll('programme')].map(p=>({channel:p.getAttribute('channel'),start:date(p.getAttribute('start')),end:date(p.getAttribute('stop')),title:p.querySelector('title')?.textContent||'',description:p.querySelector('desc')?.textContent||''}));message='Guida TV caricata.';}catch{message='EPG non disponibile. Controlla URL, formato XMLTV e permessi CORS.';}}
function now(c){return programs.find(p=>p.channel===c.tvg&&p.start<=clock&&p.end>clock)}
function next(c){return programs.filter(p=>p.channel===c.tvg&&p.start>clock).sort((a,b)=>a.start-b.start)[0]}
function time(t){return new Date(t).toLocaleTimeString('it',{hour:'2-digit',minute:'2-digit'})}
function stop(){hls?.destroy();hls=null;if(video){video.pause();video.removeAttribute('src');video.load();}}
async function play(c){stop();selected=c;page='player';message='';await tick();if(video.canPlayType('application/vnd.apple.mpegurl'))video.src=c.url;else if(Hls.isSupported()&&/\.m3u8(?:[?#]|$)/i.test(c.url)){hls=new Hls();hls.loadSource(c.url);hls.attachMedia(video);hls.on(Hls.Events.ERROR,(_,d)=>{if(d.fatal)message='Stream non disponibile: verifica formato, connessione e CORS.';});}else video.src=c.url;video.play().catch(()=>{});}
function nav(p){stop();page=p;message='';}
function demo(){let p={id:crypto.randomUUID(),name:'Playlist di esempio',channels:[{name:'Big Buck Bunny',group:'Demo',tvg:'',url:'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8'},{name:'Sintel',group:'Demo',tvg:'',url:'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4'}],updated:Date.now(),source:'',epg:''};lists=[...lists,p];active=p.id;save();page='channels';programs=[];}
function keys(e){if(e.key==='Escape'){nav('channels');return}if(!['ArrowDown','ArrowUp'].includes(e.key)||['INPUT','SELECT','VIDEO'].includes(document.activeElement.tagName))return;let a=[...document.querySelectorAll('button,input,select,a')].filter(x=>x.offsetParent!==null&&!x.disabled);let i=a.indexOf(document.activeElement);a[(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length]?.focus();e.preventDefault();}
</script>
<svelte:window onkeydown={keys}/>
<div class="shell">
<aside><a class="brand" href="#home" onclick={()=>nav('playlists')}><span class="mark">◒</span> ONDA<span class="beta">BETA</span></a><div class="navlabel">IL TUO SPAZIO TV</div><button class:chosen={page==='channels'} onclick={()=>nav('channels')}>▦ <span>Canali e guida</span></button><button class:chosen={page==='playlists'} onclick={()=>nav('playlists')}>▤ <span>Le mie playlist</span></button><button onclick={()=>{nav('channels');group='Preferiti'}}>♡ <span>Preferiti</span><small>{favorites.length}</small></button><div class="asidebottom"><span class="dot"></span> Tutto sul tuo dispositivo<p>Nessun account. Solo la tua TV.</p><small>ONDA / VERSIONE 0.1</small></div></aside>
<main><header><span>{page==='playlists'?'LIBRERIA':page==='player'?'IN RIPRODUZIONE':'DIRETTA TV'}</span><div><span class="dot"></span> Client side <span class="clock">{time(clock)}</span></div></header>
{#if message}<div class="notice" role="status">{message}<button onclick={()=>message=''} aria-label="Chiudi messaggio">×</button></div>{/if}
{#if page==='playlists'}
<div class="heading"><div><p class="eyebrow">LA TV, A MODO TUO</p><h1>Le mie playlist<span>.</span></h1><p>Un posto per tutti i tuoi canali. Il resto rimane fuori.</p></div><span class="counter">{lists.length} playlist</span></div>
<div class="importgrid"><section class="panel"><div class="sectiontitle"><span class="iconbox">＋</span><div><h2>Aggiungi una playlist</h2><p>Collega una sorgente e inizia a guardare.</p></div></div><label>Nome della playlist<input bind:value={name} placeholder="Es. TV di casa"/></label><label>Link M3U<input bind:value={url} type="url" placeholder="https://esempio.it/playlist.m3u"/></label><label>Guida TV · opzionale<input bind:value={epgUrl} type="url" placeholder="URL della guida XMLTV"/></label><button class="primary full" disabled={busy||!url} onclick={()=>add() }>{busy?'Caricamento…':'Aggiungi playlist'} <span>↗</span></button><div class="divider">oppure</div><label class="upload">↥ <b>Carica un file M3U</b><span>Scegli un file dal dispositivo</span><input type="file" accept=".m3u,.m3u8" disabled={busy} onchange={e=>{if(e.target.files[0])add(e.target.files[0]);e.target.value=''}}/></label></section><section class="intro"><div class="orbit">◒</div><p class="eyebrow">MENO DISTRAZIONI. PIÙ TV.</p><h2>Premi play.<br/>Sentiti a casa.</h2><p>Le tue playlist, i tuoi preferiti e una guida essenziale. Tutto in un’interfaccia che lascia spazio a ciò che guardi.</p><button class="textbutton" onclick={demo}>Esplora con una playlist demo ↗</button><small>Due video di esempio · nessun canale incluso</small></section></div>
<div class="sectionrow"><h2>La tua raccolta</h2><span>Salvata in questo browser</span></div>{#if !lists.length}<div class="empty compact">La tua prossima visione comincia qui.<p>Aggiungi la prima playlist o esplora la demo.</p></div>{/if}<div class="collection">{#each lists as p}<article class="playlistcard"><span class="iconbox">▤</span><h3>{p.name}</h3><p>{p.channels.length} canali · {p.source?'Sorgente online':'File locale'}</p><small>Aggiornata {new Date(p.updated).toLocaleDateString('it')}</small><div class="actions"><button class="primary" onclick={()=>{active=p.id;group='Tutti';page='channels';loadEpg()}}>Apri →</button>{#if p.source}<button disabled={busy} onclick={()=>refresh(p)}>Aggiorna</button>{/if}<button onclick={()=>remove(p.id)} aria-label={'Elimina '+p.name}>Elimina</button></div></article>{/each}</div>
{:else if page==='channels'}
<div class="heading"><div><p class="eyebrow">SCEGLI COSA GUARDARE</p><h1>In onda<span>.</span></h1><p>I tuoi canali, senza rumore.</p></div><select bind:value={active} onchange={()=>{group='Tutti';loadEpg()}} aria-label="Playlist">{#each lists as p}<option value={p.id}>{p.name}</option>{/each}</select></div>
{#if channels.length}<div class="toolbar"><input class="search" bind:value={query} placeholder="⌕  Cerca un canale…" aria-label="Cerca canale"/><label class="epgbutton">↥ Importa EPG<input type="file" accept=".xml" onchange={e=>{if(e.target.files[0])loadEpg(e.target.files[0]);e.target.value=''}}/></label></div><div class="chips">{#each groups as g}<button class:active={group===g} onclick={()=>group=g}>{g}</button>{/each}</div><div class="sectionrow"><span>{filtered.length} CANALI</span><span>IN ONDA / A SEGUIRE</span></div><div class="channels">{#each filtered.slice(0,500) as c,i}<article class="channel"><button class="channelmain" onclick={()=>play(c)}><span class="num">{String(i+1).padStart(2,'0')}</span><span class="channelicon">{#if c.logo}<img src={c.logo} alt="" loading="lazy" onerror={e=>e.target.style.display='none'}/>{:else}{c.name.slice(0,2).toUpperCase()}{/if}</span><div><h3>{c.name}</h3><p>{c.group}</p></div><div class="program"><b>{now(c)?.title||'Programmazione non disponibile'}</b><p>{next(c)?time(next(c).start)+' · '+next(c).title:'Importa una guida XMLTV per vedere i programmi'}</p></div><span class="playicon">▶</span></button><button class="fav" aria-label="Preferito" aria-pressed={favorites.includes(c.url)} onclick={()=>favorite(c)}>{favorites.includes(c.url)?'♥':'♡'}</button></article>{/each}</div>{#if filtered.length>500}<p>Mostrati i primi 500 risultati. Usa ricerca o categorie per restringere l’elenco.</p>{/if}{:else}<div class="empty"><h2>Il tuo schermo ti aspetta.</h2><p>Aggiungi una playlist per trovare qui tutti i tuoi canali.</p><button class="primary" onclick={()=>nav('playlists')}>Aggiungi playlist ↗</button></div>{/if}
{:else}
<button class="textbutton" onclick={()=>nav('channels')}>← Torna ai canali</button><div class="player"><video bind:this={video} controls autoplay playsinline onerror={()=>message='Impossibile riprodurre questo stream. Il formato o la sorgente potrebbero non essere compatibili con il browser.'}><track kind="captions"/></video></div><div class="heading"><div><p class="eyebrow">{selected?.group}</p><h1>{selected?.name}</h1><p>{now(selected)?.title||'Guida TV non disponibile'}</p></div><button onclick={()=>favorite(selected)}>{favorites.includes(selected.url)?'♥ Nei preferiti':'♡ Aggiungi ai preferiti'}</button></div><div class="actions"><button onclick={()=>{let i=channels.findIndex(c=>c.url===selected.url);play(channels[(i-1+channels.length)%channels.length])}}>← Precedente</button><button class="primary" onclick={()=>play(selected)}>Riprova ↻</button><button onclick={()=>{let i=channels.findIndex(c=>c.url===selected.url);play(channels[(i+1)%channels.length])}}>Successivo →</button></div>
{/if}<footer>ONDA <span>La tua TV. Il tuo ritmo.</span><span>Playlist e preferiti restano su questo dispositivo.</span></footer></main></div>
